// Üretilen dosya: tool/ozgun/uret.py. Tarih · Türk-İslam devletleri ve Selçuklular (zor).
const ozHistory2Zor = <(String, String, List<String>, String)>[
  ('Abbasi ordusunda görev yapan ve Babek isyanını bastırmasıyla tanınan Türk komutan kimdir?', 'Afşin', ['Boğa el-Kebir', 'Eşnas', 'Vasif'], 'Uşrusanalı Afşin Haydar, Halife Mutasım döneminde uzun süren Babek Hürremi isyanını 837\'de bastırdı.'),
  ('Abbasi sınır bölgelerinde Bizans\'a karşı kurulan ve Türk askerlerinin yerleştirildiği sınır boylarına ne ad verilirdi?', 'Avasım ve sugur', ['Ribat ve tekke', 'İkta ve has bölgeleri', 'Dirlik ve tımar'], 'Avasım ve sugur, Abbasilerin Bizans sınırındaki savunma bölgeleriydi; Türk askerleri bu bölgelerde Bizanslılarla mücadele ederek Anadolu\'yu tanıdı.'),
  ('\'İhşid\' unvanı Abbasi halifesi tarafından Muhammed bin Tuğç\'a verilmiştir. Bu unvan aslen hangi kültür çevresine aittir?', 'Fergana ve Maveraünnehir hükümdarlarına', ['Bizans\'taki imparatorluk sarayı görevlilerine', 'Endülüs Emevi emirlerine', 'Hazar kağanlarına'], 'İhşid, Fergana bölgesi hükümdarlarının kullandığı eski bir unvandı; Muhammed bin Tuğç\'un ailesi de Fergana kökenliydi.'),
  ('Karahanlılar döneminde 960 yılında yaşandığı kaydedilen ve kaynaklarda \'200 bin çadırlık Türk topluluğu Müslüman oldu\' şeklinde anlatılan gelişme hangi hükümdar dönemindedir?', 'Musa Baytaş Han', ['Satuk Buğra Han', 'Yusuf Kadir Han', 'Arslan İlig Nasr Han'], 'Satuk Buğra Han\'ın oğlu Musa Baytaş Han döneminde İslamiyet resmî din hâline geldi ve büyük Türk toplulukları Müslüman oldu.'),
  ('Karahanlılardaki ikili teşkilatta büyük hükümdar \'Arslan Kara Hakan\' unvanını taşırken, batıdaki ikinci hükümdar hangi unvanı kullanırdı?', 'Buğra Kara Hakan', ['Tonga Alp Er Hakan', 'İlig Tegin', 'Tarkan Han'], 'Doğudaki büyük hakan Arslan Kara Hakan, batıdaki küçük hakan Buğra Kara Hakan unvanını taşırdı; bu, eski Türk ikili teşkilatının devamıdır.'),
  ('Karahanlı hükümdarlarından Tamgaç Buğra Han (İbrahim) Semerkant\'ta hangi tür bir kurum yaptırmasıyla tanınır?', 'Hastane ve medrese', ['Rasathane ve kütüphane', 'Tersane ve liman', 'Kervansaray ve bedesten'], 'Tamgaç Buğra Han Semerkant\'ta bir medrese ve hastane yaptırarak vakıf gelirleri bağladı; bu, Türk-İslam sosyal kurumlarının erken örneklerindendir.'),
  ('Kutadgu Bilig\'de adalet, devlet, akıl ve kanaat (akıbet) kavramlarını temsil eden dört karakter aşağıdakilerden hangisinde doğru eşleştirilmiştir?', 'Kün Toğdı: adalet, Ay Toldı: devlet', ['Kün Toğdı: akıl, Odgurmış: devlet ve talih', 'Ay Toldı: kanaat, Ögdülmiş: adalet', 'Odgurmış: adalet, Kün Toğdı: akıl'], 'Kün Toğdı hükümdarı ve adaleti, Ay Toldı devleti ve talihi, Ögdülmiş aklı, Odgurmış ise akıbeti ve kanaati simgeler.'),
  ('Yusuf Has Hacip Kutadgu Bilig\'i hangi Karahanlı hükümdarına sunmuştur?', 'Tabgaç Buğra Kara Han', ['Satuk Buğra Han', 'Arslan Han Muhammed bin Süleyman', 'Musa Baytaş Han'], 'Eser 1069-1070 yılında Kaşgar\'da tamamlanıp Tabgaç Buğra Kara Han Hasan bin Süleyman\'a sunuldu; yazar \'Has Hacip\' unvanını bu sayede aldı.'),
  ('Gazneli Mahmut dönemi olaylarını anlatan \'Tarih-i Yemini\' adlı eserin yazarı kimdir?', 'Utbi', ['Beyhaki', 'Gerdizi', 'Firdevsi'], 'Utbi eserine, Mahmut\'un \'Yeminü\'d-Devle\' unvanından dolayı Tarih-i Yemini adını verdi.'),
  ('Gaznelilerin, Hindistan\'daki son topraklarını da kaybederek 1187\'de tarihten silinmesine yol açan devlet hangisidir?', 'Gurlular', ['Harzemşahlar', 'Karahanlılar', 'Delhi Sultanlığı'], 'Dandanakan\'dan sonra Hindistan\'a çekilen Gazneliler, Gurlular tarafından 1187\'de Lahor\'un alınmasıyla yıkıldı.'),
  ('Selçuk Bey\'in oğlu olan ve Gazneli Mahmut tarafından tutuklanarak Kalincar Kalesi\'nde hapsedilen Selçuklu beyi kimdir?', 'Arslan Yabgu', ['Mikail', 'Musa İnanç Yabgu', 'Yusuf İnal'], 'Arslan Yabgu, Gazneli Mahmut ile yaptığı görüşme sonrasında tutuklandı ve ölümüne kadar Hindistan\'da hapsedildi.'),
  ('Tuğrul Bey Bağdat\'tan ayrıldığında halifeye karşı ayaklanarak Bağdat\'ta Fatımiler adına hutbe okutan Türk komutan kimdir?', 'Besasiri', ['Kutalmış', 'İbrahim Yinal', 'Afşin'], 'Besasiri 1058\'de Bağdat\'ı ele geçirip Fatımi halifesi adına hutbe okuttu; Tuğrul Bey 1059\'da Bağdat\'ı geri alıp onu ortadan kaldırdı.'),
  ('Katvan Savaşı\'nda Sultan Sencer\'i yenen Karahıtaylar ile ilgili olarak aşağıdakilerden hangisi doğrudur?', 'Kuzey Çin\'den batıya göç etmiş Moğol kökenli bir topluluktur', ['Bizans\'ın Anadolu\'ya sınır muhafızı olarak yerleştirdiği Hristiyan bir topluluktur', 'Fatımilere bağlı Arap kabilelerinin birliğidir', 'Türkmenlerden oluşan bir Oğuz boyudur'], 'Karahıtaylar Kuzey Çin\'deki Liao (Kitan) Devleti\'nin yıkılmasından sonra batıya gelen ve Budist olan bir topluluktu.'),
  ('Selçuklu ordusunda sultanın doğrudan emrinde bulunan, maaşlı ve sürekli hazır kuvvete ne ad verilirdi?', 'Gulaman-ı saray', ['İkta askerleri', 'Türkmen aşiret kuvvetleri ve uç beyleri', 'Bağlı devlet askerleri'], 'Sultanın emrindeki gulamlar saray okullarında yetişen, maaşla çalışan profesyonel askerlerdi.'),
  ('Büyük Selçuklu Devleti\'nin bölünmesinden ortaya çıkan Selçuklu kolları arasında Kerman bölgesinde kurulan kolun kurucusu kimdir?', 'Kavurt Bey', ['Tutuş', 'Süleyman Şah', 'Mahmud'], 'Çağrı Bey\'in oğlu Kavurt Bey, Kirman (Kerman) Selçuklularını kurdu; bu kol Umman ve Basra Körfezi\'ne kadar etkili oldu.'),
  ('Irak Selçuklularının en önemli rakibi hâline gelen ve zamanla Bağdat üzerinde yeniden siyasi güç kazanmaya çalışan kurum hangisidir?', 'Abbasi halifeliği', ['Bizans İmparatorluğu', 'Fatımi halifeliği', 'Gazneli sultanlığı'], 'Irak Selçukluları zayıfladıkça Abbasi halifeleri bağımsız hareket etmeye başladı; Halife Nasır, Harzemşahlarla iş birliği yaparak 1194\'te Irak Selçuklularının yıkılmasına zemin hazırladı.'),
  ('Dımaşk\'ta Tuğtekin tarafından kurulan ve adını oğlu Böri\'den alan atabeylik hangisidir?', 'Böriler', ['Zengiler', 'Beytigin', 'Ahmedililer'], 'Tuğtekin, Suriye Selçuklu meliki Dukak\'ın atabeyiydi; onun soyundan gelenler Böriler adıyla Dımaşk\'ı yönetti.'),
  ('Azerbaycan ve Arran bölgesinde hüküm süren, Irak Selçuklu sultanları üzerinde büyük etkisi olan ve sonunda Harzemşahlar tarafından ortadan kaldırılan atabeylik hangisidir?', 'İldenizliler', ['Salgurlu Atabeyleri', 'Zengiler', 'Böriler'], 'Şemseddin İldeniz\'in kurduğu atabeylik Irak Selçuklu sultanlarını denetimi altına aldı; 1225\'te Celaleddin Harzemşah tarafından yıkıldı.'),
  ('Celaleddin Harzemşah\'ın 1229\'da uzun bir kuşatmadan sonra ele geçirdiği ve Yassıçemen Savaşı\'nın nedenlerinden sayılan şehir hangisidir?', 'Ahlat', ['Sivas', 'Malatya', 'Kayseri'], 'Celaleddin\'in Eyyubilere ait Ahlat\'ı alması, Anadolu Selçukluları ile Eyyubileri ona karşı birleştirdi.'),
  ('Celaleddin Harzemşah\'ın ölümünden sonra Anadolu\'ya ve Suriye\'ye dağılan Harzemli askerler, 1244\'te hangi şehrin kesin olarak Müslümanların eline geçmesinde rol oynamıştır?', 'Kudüs', ['Akka', 'Antakya', 'İskenderiye'], 'Eyyubilerin hizmetine giren Harzemliler 1244\'te Kudüs\'ü Haçlılardan aldı; şehir bundan sonra uzun süre Müslümanlarda kaldı.'),
  ('Danişmentli Gümüştekin Gazi\'nin 1100\'de esir aldığı ve uzun süre tutsak tuttuğu kişi kimdir?', 'Antakya Prinkepsi Bohemond', ['Bizans İmparatoru I. Aleksios', 'Kudüs Kralı Baudouin', 'Kral Richard'], 'I. Haçlı Seferi\'nin önde gelen komutanlarından Bohemond, Malatya yakınlarında Danişmentlilere esir düştü ve fidye karşılığı serbest bırakıldı.'),
  ('Artuklu Beyliği\'nden İlgazi\'nin 1119\'da Antakya Prinkepsliği ordusunu ağır bir yenilgiye uğrattığı savaş Batı kaynaklarında nasıl adlandırılır?', 'Kanlı Ova', ['Hıttin (Hattin) Savaşı', 'Dorylaion Savaşı', 'Ayn Calut Savaşı'], 'İlgazi, Antakya Prinkepsi Roger\'ı Sarmeda yakınlarında yendi; Haçlı ordusu neredeyse tamamen yok edildi.'),
  ('Batman Çayı üzerinde Artuklular tarafından yaptırılan ve dönemin en büyük taş kemerli köprülerinden sayılan yapı hangisidir?', 'Malabadi Köprüsü', ['Uzun Köprü', 'Çobandede Köprüsü', 'Taşköprü'], 'Silvan ile Batman arasındaki Batman Çayı üzerindeki Malabadi Köprüsü 1147\'de Artuklu döneminde tamamlandı.'),
  ('Türkiye Selçuklu Devleti\'nin kurucusu Süleyman Şah, Kutalmış\'ın oğludur. Kutalmış ise hangi Selçuklu beyinin oğludur?', 'Arslan Yabgu', ['Mikail bin Selçuk', 'Çağrı Bey', 'Musa Yabgu'], 'Kutalmış, Selçuk Bey\'in oğlu Arslan Yabgu\'nun oğluydu; bu nedenle Türkiye Selçukluları Arslan Yabgu soyundan gelir.'),
  ('I. Kılıçarslan 1107\'de Büyük Selçuklulara karşı hangi şehri alarak doğuya açılmak istemiş, ancak Habur Çayı\'nda yenilerek boğulmuştur?', 'Musul', ['Halep', 'Bağdat', 'Tebriz'], 'Kılıçarslan Musul\'u alarak Büyük Selçuklulardan bağımsızlığını pekiştirmek istedi; Habur Çayı kıyısında yenilip nehirde boğuldu.'),
  ('Latinlerin 1204\'te İstanbul\'u işgali üzerine Bizans soylularının kurduğu ve Türkiye Selçuklularıyla komşu olan devlet hangisidir?', 'İznik İmparatorluğu', ['Trabzon Rum İmparatorluğu', 'Kilikya Ermeni Krallığı', 'Epir Despotluğu'], 'Laskarisler tarafından kurulan İznik İmparatorluğu Batı Anadolu\'da Selçuklularla komşu oldu; Trabzon Rum İmparatorluğu ise Karadeniz kıyısındaydı.'),
  ('I. Gıyaseddin Keyhüsrev 1211\'de İznik İmparatoru Theodoros Laskaris ile yaptığı hangi savaşta hayatını kaybetmiştir?', 'Alaşehir Savaşı', ['Miryokefalon Savaşı', 'Kösedağ Savaşı', 'Yassıçemen Savaşı'], 'Alaşehir (Antiokheia ad Maeandrum) yakınlarındaki savaşı Selçuklular kazanmaya yakınken sultan şehit düştü.'),
  ('Kösedağ\'dan sonra Selçuklu devlet yönetiminde etkili olan, \'pervane\' unvanıyla tanınan ve Moğollarla Memlükler arasında denge politikası izleyen devlet adamı kimdir?', 'Muineddin Süleyman Pervane', ['Celaleddin Karatay', 'Sahip Ata Fahreddin Ali bin Hüseyin', 'Sadeddin Köpek'], 'Muineddin Süleyman Pervane uzun süre devleti fiilen yönetti; Baybars\'ın Anadolu seferiyle bağlantısı nedeniyle Moğollarca idam edildi.'),
  ('Türkiye Selçuklu Devleti\'nin son sultanı olarak kabul edilen ve 1308 dolaylarında ölümüyle devletin sona erdiği hükümdar kimdir?', 'II. Mesud', ['III. Alaeddin Keykubat', 'IV. Kılıçarslan', 'II. İzzeddin Keykavus'], 'II. Gıyaseddin Mesud\'un ölümüyle Türkiye Selçuklu hanedanı fiilen sona erdi; topraklar İlhanlı valileri ve beyliklerin eline geçti.'),
  ('İlhanlı veziri Reşidüddin Fazlullah\'ın Türk ve Moğol tarihini de kapsayan ünlü tarih eseri hangisidir?', 'Câmiü\'t-Tevârîh', ['Tarih-i Cihan-güşa', 'Selçukname', 'Zafername'], 'Reşidüddin\'in Câmiü\'t-Tevârîh\'i Oğuz destanını ve Türk boylarını da anlatan, dünya tarihi niteliğinde bir eserdir.'),
  ('Selçuklu döneminde Kayseri yakınlarında kurulan ve dönemin uluslararası pazarlarından biri olan panayır hangisidir?', 'Yabanlu Pazarı', ['Sudak Pazarı', 'Bergama Panayırı', 'Bursa Bedesteni'], 'Yabanlu Pazarı\'nda Doğu ve Batı\'dan gelen tüccarlar haftalarca alışveriş yapar, uluslararası ticaret gerçekleşirdi.'),
  ('Selçuklu kervansaraylarında, içinde bulunan tüccarların ibadet etmesi için avlunun ortasına yapılan küçük yapıya ne ad verilir?', 'Köşk mescit', ['Şadırvan havuzu', 'Kümbet', 'Tekke'], 'Pek çok Selçuklu kervansarayında avlu ortasında kemerler üzerinde yükselen köşk mescitler bulunur.'),
  ('Kayseri\'de Alaeddin Keykubat\'ın eşi Mahperi Hatun tarafından yaptırılan ve cami, medrese, hamam ve türbeden oluşan yapı topluluğu hangisidir?', 'Hunat Hatun Külliyesi', ['Gevher Nesibe Külliyesi', 'Sahip Ata Külliyesi', 'Döner Kümbet'], 'Mahperi Hatun, Hunat Hatun olarak da bilinir; Kayseri\'deki külliye 1238 dolaylarında tamamlanmıştır.'),
  ('Âşıkpaşazade\'nin Anadolu\'daki dört zümre arasında saydığı Gaziyan-ı Rum ne ifade eder?', 'Uç bölgelerde gaza yapan savaşçı Türkmenleri', ['Anadolu\'daki kadınların örgütlendiği teşkilatı', 'Medrese öğrencilerini', 'Saray görevlilerini'], 'Gaziyan-ı Rum uçlarda Bizans\'a karşı gaza yapan savaşçılardı; diğer zümreler Ahiyan, Abdalan ve Bacıyan-ı Rum\'dur.'),
  ('Türkiye Selçuklularında sultan adına ikta beratlarını düzenleyen ve sonradan devlet yönetiminde çok etkili hâle gelen görevli hangisidir?', 'Pervane', ['Müstevfi', 'Emir-i dad', 'Beylerbeyi'], 'Pervane ikta beratlarını hazırlar ve sultanın onayına sunardı; Kösedağ sonrası pervaneler devleti fiilen yönetti.'),
  ('Memlük Devleti\'nin kurumları arasında, uzak mesafelere hızlı haberleşme için kullanılan ve posta güvercinlerine de başvurulan teşkilat hangisidir?', 'Berid', ['Divan-ı İnşa', 'Hisbe', 'Atabeglik'], 'Memlükler berid denilen posta teşkilatını geliştirdi; atlı postacılar ve güvercinlerle haber taşındı.'),
  ('Memlük Devleti\'nin ikinci döneminde yönetimi ele geçiren ve Kahire Kalesi\'ndeki burçlarda konuşlandıkları için bu adı alan memlükler kimlerdir?', 'Burci Memlükler', ['Bahri Memlükler', 'Kıpçak Memlükleri', 'Kölemenler'], '1382\'den sonra Çerkez kökenli Burci Memlükler yönetime hâkim oldu.'),
  ('Memlük Devleti\'nin ilk sultanı olarak kabul edilen kadın hükümdar kimdir?', 'Şecerüddür', ['Turan Melek', 'Gevher Nesibe', 'Terken Hatun'], 'Eyyubi Sultanı Salih Necmeddin\'in eşi Şecerüddür 1250\'de kısa bir süre sultan oldu, ardından Aybek ile evlendi.'),
  ('Memlük sultanı Kalavun\'un Kahire\'de yaptırdığı külliyenin, Orta Çağ İslam dünyasının en büyükleri arasında sayılan bölümü hangi işlevi görüyordu?', 'Hastane', ['Rasathane', 'Tersane', 'Kütüphane'], 'Kalavun Külliyesi\'ndeki Bimaristan, Orta Çağ İslam dünyasının en büyük hastanelerinden biriydi.'),
  ('Uygur asıllı bir İlhanlı valisi tarafından Sivas ve Kayseri çevresinde kurulan beylik hangisidir?', 'Eretnaoğulları', ['Dulkadiroğulları', 'Ramazanoğulları', 'Saruhanoğulları'], 'Eretna Bey, İlhanlı valisi Timurtaş\'ın yanında bulunan Uygur kökenli bir emirdi; İlhanlıların çözülmesinden sonra beyliğini kurdu.'),
  ('Antalya-Isparta çevresinde hüküm süren ve Eğirdir\'i merkez edinen beylik hangisidir?', 'Hamitoğulları', ['Eşrefoğulları', 'Germiyanoğulları', 'Menteşeoğulları'], 'Hamitoğulları Eğirdir merkezliydi; Teke kolu da Antalya çevresinde ayrı bir yönetim kurdu.'),
  ('Selçuklularda askerî davalara bakan yargıca \'kadı-i asker\' denirken, örfi davalara bakan ve sultan adına adaleti sağlayan görevliye ne ad verilirdi?', 'Emir-i dad', ['Kadı\'l-kudat', 'Muhtesip', 'Ariz'], 'Emir-i dad, örfi davalara bakar, siyasi suçları yargılar ve sultanın adalet işlerini yürütürdü.'),
  ('Selçuklularda şehirlerin güvenliğini sağlayan ve askerî vali niteliği taşıyan görevliye ne denirdi?', 'Şıhne', ['Muhtesip', 'Kadı', 'Müstevfi'], 'Şıhne, şehirlerde asayişten sorumlu askerî yöneticiydi; Bağdat\'ta da Selçuklu sultanını bir şıhne temsil ederdi.'),
  ('Türk-İslam devletlerinde hükümdarın yetkilerinin halife tarafından onaylanmasını belgeleyen ve gönderilen yazılı belgeye ne ad verilirdi?', 'Menşur', ['Berat', 'Ahitname', 'Kanunname'], 'Halife, hükümdara menşur adı verilen bir belge ile birlikte hil\'at, sancak ve unvanlar gönderirdi.'),
  ('Selçuklularda sultanın başı üzerinde taşınan ve hükümdarlık sembolü olan şemsiyeye ne ad verilirdi?', 'Çetr', ['Tuğ', 'Otağ', 'Nevbet'], 'Çetr, sultanın törenlerde ve seferlerde başının üzerinde tutulan hükümdarlık şemsiyesiydi.'),
  ('Timurlu sarayında yetişen ve Herat okulunun en ünlü minyatür sanatçısı olarak kabul edilen ressam kimdir?', 'Bihzad', ['Matrakçı Nasuh', 'Levni', 'Siyah Kalem'], 'Kemaleddin Bihzad, Hüseyin Baykara döneminde Herat\'ta çalıştı ve İslam minyatür sanatının ustası sayıldı.'),
  ('Timur\'un 1395\'te Terek Irmağı kıyısında yendiği ve bu yenilgiyle büyük ölçüde gücünü yitiren Türk-Moğol devleti hangisidir?', 'Altın Orda', ['Çağatay Hanlığı', 'Memlük Devleti', 'Delhi Sultanlığı'], 'Timur, Altın Orda hanı Toktamış\'ı yendi; Altın Orda\'nın merkez şehirleri yıkıldı ve devlet hızla zayıfladı.'),
  ('Babür İmparatorluğu\'nun kurucusu Babür Şah, soy olarak hangi iki hanedana bağlanır?', 'Baba tarafından Timur\'a, anne tarafından Cengiz\'e', ['Baba tarafından Selçuk\'a, anne tarafından Gazne\'ye', 'Baba tarafından Osman\'a, anne tarafından Timur\'a', 'Baba tarafından Cengiz\'e, anne tarafından Karahanlılara'], 'Babür, babası Ömer Şeyh Mirza üzerinden Timur\'un, annesi üzerinden Cengiz Han\'ın soyundandır.'),
  ('Babür hükümdarı Ekber Şah\'ın farklı dinlerin ortak noktalarını bir araya getirmeye çalıştığı inanç anlayışına ne ad verilir?', 'Din-i İlahi', ['Vahdet-i Vücud', 'Bhakti', 'Sih dini'], 'Ekber Şah, Hindu ve Müslüman tebaası arasında barışı sağlamak amacıyla Din-i İlahi adıyla bir uzlaşma anlayışı geliştirdi.'),
  ('Akkoyunlu hükümdarı Uzun Hasan\'ın vergi düzenini belirleyen ve sonraki devletlerde de uygulanan kanunlarına ne ad verilir?', 'Hasan Padişah Kanunları', ['Cengiz Yasası', 'Siyasetname', 'Kutadgu Bilig'], 'Uzun Hasan\'ın kanunnameleri, Doğu Anadolu ve İran\'daki vergi düzenini uzun süre etkiledi.'),
  ('Selçuklu çini sanatında yıldız ve haç biçimli çinilerle insan ve hayvan figürlerinin kullanıldığı en zengin örnekler hangi yapıdan çıkarılmıştır?', 'Kubadabad Sarayı', ['Divriği Ulu Camii', 'Sultanhanı', 'Alanya Kızıl Kule'], 'Kubadabad Sarayı\'ndan çıkan sır üstü ve sır altı figürlü çiniler, Selçuklu saray çiniciliğinin başlıca örnekleridir.'),
  ('Selçuklu döneminde ağaç parçalarının çivi ya da tutkal kullanılmadan geçme yöntemiyle birleştirildiği ahşap işçiliği tekniğine ne ad verilir?', 'Kündekari', ['Mukarnas', 'Ebru', 'Tezhip'], 'Kündekari tekniği özellikle minber ve kapılarda kullanıldı; Ankara Arslanhane Camii minberi bunun örneklerindendir.'),
  ('Buhara\'da bulunan ve 1127\'de Karahanlı hükümdarı Arslan Han tarafından yaptırılan, tuğla süslemeli ünlü minare hangisidir?', 'Kalyan Minaresi', ['Kutub Minar', 'Yivli Minare', 'Gur-i Emir'], 'Kalyan (Büyük) Minaresi yaklaşık 46 metre yüksekliğiyle Karahanlı tuğla mimarisinin en ünlü örneğidir.'),
  ('Karahanlılar ve Gazneliler arasındaki sınır, 1001\'de iki devlet arasında yapılan anlaşmayla hangi nehir olarak belirlenmiştir?', 'Ceyhun (Amuderya)', ['Seyhun (Siriderya)', 'İdil (Volga)', 'Sind (İndus)'], 'Samanoğullarının yıkılmasından sonra Karahanlılar Maveraünnehir\'i, Gazneliler Horasan\'ı aldı; Ceyhun iki devlet arasında sınır oldu.'),
  ('Selçuklu Sultanı Tuğrul Bey\'in veziri olan ve sonradan Alparslan döneminde öldürülen devlet adamı kimdir?', 'Amidülmülk Kündüri', ['Nizamülmülk', 'Tacülmülk', 'Sadeddin Köpek'], 'Kündüri, Tuğrul Bey\'in veziriydi; Alparslan\'ın tahta çıkmasından sonra yerini Nizamülmülk aldı ve 1064\'te idam edildi.'),
  ('Tuğrul Bey\'in 1043\'te başkent yaptığı ve uzun süre Büyük Selçuklu merkezi olan İran şehri hangisidir?', 'Rey', ['Merv', 'İsfahan', 'Hemedan'], 'Tuğrul Bey Rey\'i başkent yaptı; Melikşah döneminde ise İsfahan merkez oldu.'),
  ('Selçuklu döneminde İran\'da geliştirilen ve dört eyvanlı avlu planını cami mimarisine uygulayan yapı tipinin bilinen en etkili örneği hangisidir?', 'İsfahan Mescid-i Cuma', ['İbn Tolun Camii', 'Divriği Ulu Camii', 'Emevi Camii'], 'İsfahan Mescid-i Cuma, Selçuklu döneminde dört eyvanlı plana dönüştürülmüş ve bu plan İran camilerinde yaygınlaşmıştır.'),
  ('Ömer Hayyam\'ın bilim insanı kimliğiyle ilgili olarak aşağıdakilerden hangisi doğrudur?', 'Kübik denklemlerin geometrik çözümü üzerine çalışmıştır', ['Kâğıdı Çin\'den İslam dünyasına getirmiştir', 'Divanü Lügati\'t-Türk\'ü yazmıştır', 'İlk Türk haritasını çizmiştir'], 'Ömer Hayyam matematikte kübik denklemleri konik kesitlerle çözmüş, ayrıca Celali Takvimi çalışmalarında yer almıştır.'),
  ('Melikşah döneminde Kudüs\'ü Fatımilerden alarak Suriye ve Filistin\'de Selçuklu egemenliğini genişleten Türkmen beyi kimdir?', 'Atsız Bey', ['Artuk Bey', 'Çaka Bey', 'Danişment Gazi'], 'Atsız bin Uvak 1071 dolaylarında Kudüs\'ü, ardından Dımaşk\'ı ele geçirdi.'),
  ('Kösedağ\'dan sonra Moğol baskısıyla Bizans\'a sığınan ve hayatının sonunu Kırım\'da geçiren Türkiye Selçuklu sultanı kimdir?', 'II. İzzeddin Keykavus', ['IV. Kılıçarslan', 'III. Gıyaseddin Keyhüsrev', 'II. Mesud'], 'II. İzzeddin Keykavus Moğollarla anlaşamayınca Bizans\'a sığındı; sonrasında Altın Orda\'ya geçti ve Kırım\'da öldü.'),
  ('Harzemşah ülkesinin başkenti olan ve Amuderya deltası yakınında bulunan şehir hangisidir?', 'Gürgenç', ['Otrar', 'Merv', 'Herat'], 'Harezm bölgesinin merkezi Gürgenç, Moğol istilasında 1221\'de yıkıldı.'),
  ('Harzemşah hükümdarı Tekiş\'in 1194\'te Irak Selçuklu sultanı III. Tuğrul\'u yenmesinin sonucu nedir?', 'Irak Selçuklu Devleti\'nin sona ermesi', ['Harzemşahların Moğollara bağlanması', 'Tuğrul\'un Bağdat\'ta halife olması', 'Harzemşahların Anadolu\'ya göçmesi'], 'Rey yakınlarındaki savaşta III. Tuğrul öldürüldü; Büyük Selçuklu ailesinin İran\'daki son kolu böylece ortadan kalktı.'),
  ('Türk-İslam dünyasında sınır boylarında kurulan ve hem askerî karakol hem de dervişlerin barındığı yapı olarak kullanılan yapıya ne ad verilirdi?', 'Ribat', ['Bedesten', 'İmaret', 'Kümbet'], 'Ribatlar sınırlarda gaziler ve sufilerin kaldığı müstahkem yapılardı; zamanla yol üzerinde konaklama yerlerine de bu ad verildi.'),
  ('Selçuklu medreselerinde dersi veren öğretim üyesine müderris denirken, müderrisin yardımcısı olup dersleri tekrarlatan görevliye ne denirdi?', 'Muid', ['Kadı', 'Danişmend', 'Naib'], 'Muid, müderrisin anlattığı dersleri öğrencilere tekrar ettiren asistan niteliğinde bir görevliydi.'),
  ('Kırşehir\'de 1272\'de yaptırılan ve astronomi eğitimi verildiği bilinen Selçuklu medresesi hangisidir?', 'Cacabey Medresesi', ['Karatay Medresesi', 'Gök Medrese', 'Buruciye Medresesi'], 'Nureddin Cebrail bin Caca Bey\'in yaptırdığı medresede astronomi gözlemleri ve eğitimi yapıldığı kabul edilir; bugün camiye dönüştürülmüştür.'),
  ('Ahmed bin Tolun\'un babası Tolun\'un Abbasi sarayına nasıl geldiği kaynaklarda nasıl anlatılır?', 'Buhara valisinin halifeye gönderdiği Türk gulamlar arasında', ['Bizans elçisi olarak', 'Hazar kağanının oğlu olarak', 'Fatımi komutanı olarak'], 'Tolun, Samanoğulları bölgesinden halifeye hediye olarak gönderilen Türk gulamlardan biriydi ve sarayda yükseldi.'),
  ('İhşidi Devleti\'nde Muhammed bin Tuğç\'un ölümünden sonra yönetimi fiilen eline alan, Habeş kökenli bir köle olan naip kimdir?', 'Kafur', ['Humareveyh', 'Besasiri', 'Şirkuh'], 'Kafur, İhşid\'in oğullarının naibi olarak yönetimi yürüttü, 966\'da resmen hükümdar oldu.'),
  ('Gazneli Mahmut\'un 1029\'da Büveyhoğullarından aldığı ve Batıni-Şii unsurları cezalandırdığı İran şehri hangisidir?', 'Rey', ['Bağdat', 'Hemedan', 'Nişabur'], 'Rey\'in alınması Gaznelilerin batıdaki en önemli kazanımıydı; Gazneli Mahmut bu zaferi halifeye bildirdi.'),
  ('Tuğrul Bey\'in 1038\'de girdiği ve adına hutbe okutarak sultanlığını ilk kez ilan ettiği şehir hangisidir?', 'Nişabur', ['Bağdat', 'Merv', 'Rey'], 'Tuğrul Bey 1038\'de Nişabur\'a girdi ve burada tahta oturarak adına hutbe okuttu.'),
  ('Alparslan\'ın Malazgirt\'ten önce Ani\'yi fethetmesinden dolayı Abbasi halifesinden aldığı unvan hangisidir?', 'Ebu\'l-Feth', ['Sultanü\'l-Meşrık', 'Muizzüddin', 'Gıyaseddin'], 'Ani\'nin alınması İslam dünyasında büyük sevinçle karşılandı; halife Alparslan\'a \'Ebu\'l-Feth\' (Fetihlerin babası) unvanını verdi.'),
  ('Memlük sultanı Baybars\'ın biyografisi etrafında oluşan ve halk arasında yüzyıllarca anlatılan halk hikâyesi hangisidir?', 'Sîretü Baybars', ['Battalname', 'Saltukname', 'Danişmendname'], 'Sîretü\'z-Zâhir Baybars, Baybars\'ı kahraman olarak işleyen ve Arap dünyasında meddahlarca anlatılan bir halk anlatısıdır.'),
  ('Altın Orda\'nın Rus knezliklerini vergiye bağlaması ve onların yöneticilerini onaylaması, Rus tarihinde nasıl adlandırılan bir dönemi başlatmıştır?', 'Tatar boyunduruğu', ['Kiev altın çağı', 'Novgorod cumhuriyeti', 'Romanov dönemi'], 'Rus kaynaklarında 13-15. yüzyıllar arası Altın Orda egemenliği \'Tatar boyunduruğu\' olarak anılır.'),
  ('Altın Orda yönetimi altında Kıpçak Türkçesiyle yazılmış ve Kuman dilini Latin harfleriyle kaydeden ünlü sözlük hangisidir?', 'Codex Cumanicus', ['Divanü Lügati\'t-Türk', 'Kitabü\'l-İdrak', 'Muhakemetü\'l-Lügateyn'], 'Codex Cumanicus 14. yüzyılda İtalyan tüccarlar ve misyonerlerce hazırlanmış, Kıpçak Türkçesinin önemli bir kaynağıdır.'),
  ('Memlük Devleti\'nde Kıpçak Türkçesiyle eserler yazılması ve Arapça-Türkçe sözlüklerin hazırlanması neyi gösterir?', 'Türkçenin yönetici sınıf arasında yaşatıldığını', ['Arapçanın yasaklandığını', 'Halkın tamamen Türkçe konuştuğunu', 'Memlüklerin Türkçeyi bilmediğini'], 'Memlük sultanları ve emirleri Kıpçak kökenli olduğundan Türkçe sarayda yaşadı; Kitabü\'l-İdrak gibi sözlükler yazıldı.'),
  ('Memlüklerin 1250\'de Mansure\'de yendiği ve esir aldığı Fransa kralının önderlik ettiği Haçlı seferi hangisidir?', 'VII. Haçlı Seferi', ['III. Haçlı Seferi', 'IV. Haçlı Seferi', 'I. Haçlı Seferi'], 'Fransa Kralı IX. Louis Mısır\'a yürüdü; Mansure\'de durdurulup Fariskur\'da yenilerek esir alındı.'),
  ('Talas Savaşı\'nda Abbasi ordusuna komuta eden komutan kimdir?', 'Ziyad bin Salih', ['Kuteybe bin Müslim', 'Ebu Müslim Horasani', 'Haccac bin Yusuf'], 'Ziyad bin Salih, Horasan valisi Ebu Müslim\'in emriyle Çin ordusuna karşı gönderilmişti.'),
  ('Emevi halifesi Ömer bin Abdülaziz\'in mevaliye eşit davranılmasını emretmesi, Türklerle ilişkileri nasıl etkilemiştir?', 'Maveraünnehir\'de İslamiyet\'e ilgiyi artırmıştır', ['Türklerin Arapları bölgeden çıkarmasına yol açmıştır', 'Türklerin Budizm\'e geçmesini hızlandırmıştır', 'Türk-Arap ticaretini tamamen durdurmuştur'], 'Ömer bin Abdülaziz döneminde Müslüman olanlardan cizye alınmaması kararı, yerli halkların İslam\'a ilgisini artırdı.'),
  ('Hanefi mezhebinin örf ve âdete hukukta yer vermesi Türkler tarafından tercih edilmesini nasıl etkilemiştir?', 'Türk töresinin İslam hukukuyla uyumlu biçimde sürmesini kolaylaştırmıştır', ['Türklerin törelerini tamamen bırakmasına yol açmıştır', 'Türklerin Şiiliğe geçmesine neden olmuştur', 'Türklerin hukuk kuralı koymasını yasaklamıştır'], 'Örfü dikkate alan Hanefi anlayışı, töreye dayalı Türk yönetim geleneğinin örfi hukuk biçiminde sürmesine imkân verdi.'),
  ('İtikatta Türklerin çoğunluğunun benimsediği ve Semerkantlı bir âlimin adını taşıyan Sünni kelam ekolü hangisidir?', 'Maturidilik', ['Eş\'arilik', 'Mutezile', 'Selefilik'], 'Ebu Mansur el-Maturidi Semerkant\'ta yaşadı; onun kelam ekolü Türkler arasında yaygınlaştı.'),
  ('Kutadgu Bilig\'in yazıldığı ölçü ve nazım biçimi aşağıdakilerden hangisidir?', 'Aruz ölçüsüyle mesnevi', ['Hece ölçüsüyle koşma', 'Serbest ölçüyle destan', 'Aruz ölçüsüyle gazel'], 'Kutadgu Bilig aruzun \'feûlün feûlün feûlün feûl\' kalıbıyla, mesnevi biçiminde yazılmış ve aruzla yazılan ilk Türkçe eser kabul edilir.'),
  ('Divanü Lügati\'t-Türk\'ün bilinen tek nüshasının 20. yüzyılda bulunduğu şehir hangisidir?', 'İstanbul', ['Kahire', 'Bağdat', 'Semerkant'], 'Eserin bilinen tek nüshası 20. yüzyılın başlarında İstanbul\'da Ali Emiri Efendi tarafından bulundu.'),
  ('Biruni\'nin geçmiş milletlerin takvimlerini ve bayramlarını karşılaştırdığı eser hangisidir?', 'El-Âsârü\'l-Bâkiye', ['El-Kanun fi\'t-Tıb', 'Siyasetname', 'Tarih-i Yemini'], 'Biruni bu eserinde farklı toplumların takvim sistemlerini ve tarih anlayışlarını karşılaştırmalı olarak inceledi.'),
  ('Türkiye Selçuklularının Bizans\'la ilişkilerinde I. Alaeddin Keykubat döneminde dikkat çeken durum aşağıdakilerden hangisidir?', 'Batıda büyük savaşlar yerine doğuda birliğe ve ticarete öncelik verilmesi', ['Bizans\'ın Konya\'yı alması', 'Selçukluların İstanbul\'u kuşatması', 'Bizans\'a ağır vergi ödenmesi'], 'Alaeddin Keykubat, Moğol tehlikesi ve ticaret politikası nedeniyle Doğu Anadolu ve kıyılara yöneldi; Bizans\'la büyük bir savaşa girmedi.'),
  ('Anadolu Selçuklu sultanlarından I. Alaeddin Keykubat\'ın Kayseri yakınlarında yaptırdığı saray aşağıdakilerden hangisidir?', 'Keykubadiye Sarayı', ['Kubadabad Sarayı', 'Topkapı Sarayı', 'Kalehan Sarayı'], 'Kayseri\'deki Keykubadiye Sarayı 1224-1226\'da yapıldı; Beyşehir\'deki Kubadabad ise ayrı bir saraydır.'),
  ('Selçuklu döneminde Anadolu\'da işletilen ve şap madeniyle ünlü olup Cenovalı tüccarların ilgisini çeken bölge hangisidir?', 'Karahisar', ['Kütahya', 'Bergama', 'Edremit'], 'Şebinkarahisar şap madenleri boyacılıkta kullanıldığından Avrupalı tüccarlarca çok aranıyordu.'),
  ('Celaleddin Karatay\'ın Selçuklu yönetimindeki önemi aşağıdakilerden hangisiyle açıklanır?', 'Kösedağ sonrası naiplik yaparak devletin dağılmasını geciktirmesi', ['Malazgirt\'te ordu komutanı olması', 'Haçlılara karşı Kudüs\'ü savunması', 'Moğol hükümdarı olması'], 'Celaleddin Karatay II. İzzeddin Keykavus\'un naibi olarak devlet işlerini düzene sokmaya çalıştı; Karatay Medresesi\'ni yaptırdı.'),
  ('II. Gıyaseddin Keyhüsrev döneminde Selçuklu sarayında Sadeddin Köpek\'in etkili olması ve birçok komutanı ortadan kaldırması devleti nasıl etkilemiştir?', 'Deneyimli devlet adamlarını kaybettirerek devleti zayıflatmıştır', ['Devleti Moğollara karşı güçlendirmiştir', 'Ticaretin gelişmesini sağlamıştır', 'Haçlılarla ittifakı mümkün kılmıştır'], 'Sadeddin Köpek\'in entrikaları sonucunda pek çok tecrübeli emir öldürüldü; bu durum Kösedağ yenilgisine giden süreci hızlandırdı.'),
  ('Kösedağ Savaşı\'ndan sonra Moğol ordusunun ele geçirip yağmaladığı Selçuklu şehirlerinden biri, özellikle büyük kayıp vermesiyle bilinen hangisidir?', 'Kayseri', ['Antalya', 'Sinop', 'Alanya'], 'Kösedağ\'dan sonra Moğollar Sivas\'ı teslim aldı, direnen Kayseri\'yi ise yağmaladı.'),
  ('Selahaddin Eyyubi\'nin Mısır\'a Zengi ordusunun komutanı olarak gelmesi ve Fatımi halifeliğine son vermesi, Zengilerin Haçlılara karşı hangi stratejisini tamamlamıştır?', 'Mısır ve Suriye\'yi birleştirerek Haçlıları iki yönden kuşatma', ['Haçlılarla ittifak kurarak Bizans\'ı yıkma', 'Bağdat\'ı halifeden alma', 'Anadolu\'yu Selçuklulardan alma'], 'Nureddin Zengi, Mısır\'ın Sünni yönetime geçmesiyle Haçlı devletlerini kuzey ve güneyden sıkıştırmayı amaçladı; Selahaddin 1171\'de Fatımi halifeliğini kaldırdı.'),
  ('I. Haçlı Seferi\'nde uzun bir kuşatmanın ardından 1098\'de Haçlıların eline geçen ve Musul Atabeyi Kürboğa\'nın kurtarmak için geldiği şehir hangisidir?', 'Antakya', ['Halep', 'Urfa', 'Dımaşk'], 'Antakya 1098\'de Haçlılarca alındı; Kürboğa\'nın yardım ordusu da şehrin önünde yenildi.'),
  ('Urfa Kontluğu\'nun I. Haçlı Seferi sırasında kurulmasında aşağıdakilerden hangisi rol oynamıştır?', 'Baudouin\'in yerel Ermeni yöneticinin yerine geçmesi', ['Selçuklu sultanının şehri Haçlılara satması', 'Bizans\'ın şehri Haçlılara bağışlaması', 'Fatımilerin şehri Haçlılara teslim etmesi'], 'Boulogne\'lu Baudouin, Urfa\'nın Ermeni yöneticisi Thoros tarafından evlat edinildi; Thoros\'un öldürülmesinin ardından 1098\'de kontluk kuruldu.'),
  ('1101 yılında Anadolu\'dan geçmeye çalışan yeni Haçlı orduları, Türklerin ortak mücadelesi sonucunda hangi sonuçla karşılaşmıştır?', 'Büyük ölçüde yok edilmişlerdir', ['Kudüs\'e kolayca ulaşmışlardır', 'Konya\'yı ele geçirmişlerdir', 'Bizans\'la savaşmışlardır'], '1101 Haçlı Seferi olarak anılan bu girişimde Kılıçarslan ve Danişmentliler Haçlıları Merzifon ve Ereğli yakınlarında bozguna uğrattı.'),
  ('Gazneliler ile Büyük Selçuklular arasındaki temel farklardan biri aşağıdakilerden hangisidir?', 'Selçukluların Oğuz boylarının desteğine, Gaznelilerin ise gulam ordusuna dayanması', ['Gaznelilerin Sünni, Selçukluların Şii olması', 'Selçukluların Hindistan\'a yönelmesi', 'Gaznelilerin Anadolu\'yu fethetmesi'], 'Selçuklular kalabalık Türkmen kitlelerine dayanırken Gazneliler daha çok paralı ve gulam askerlerle bir ordu kurdu.'),
  ('Tolunoğulları, İhşidiler, Gazneliler ve Memlükler gibi devletlerin ortak özelliği aşağıdakilerden hangisidir?', 'Kurucularının bir devlet hizmetinde komutan ya da vali olarak yükselmesi', ['Tümünün Anadolu\'da kurulması', 'Tamamının Moğollarca yıkılması', 'Ortak bir başkentten yönetilmeleri'], 'Bu devletleri kuranlar başka bir devletin hizmetinde yükselmiş Türk komutan, vali ya da memluklardı.'),
  ('Türkiye Selçuklu Devleti 1075\'te kurulmuş ve 1308 dolaylarında sona ermiştir. Kösedağ Savaşı\'na kadar geçen bağımsızlık süresi ile Kösedağ\'dan yıkılışa kadar geçen süre karşılaştırıldığında hangisi doğrudur?', 'Bağımsız dönem yaklaşık 168 yıl, bağımlı dönem yaklaşık 65 yıldır', ['Bağımsız dönem yaklaşık 65 yıl, bağımlı dönem yaklaşık 168 yıldır', 'İki dönem de yaklaşık 100 yıldır', 'Bağımsız dönem yaklaşık 233 yıldır'], '1243 - 1075 = 168 yıl; 1308 - 1243 = 65 yıl. Devlet yaşamının büyük bölümünü bağımsız geçirmiştir.'),
  ('Gurlular Devleti\'nin Gaznelilerin yerini alarak kuzey Hindistan\'a yayılması, Delhi Türk Sultanlığı\'nın kuruluşuna nasıl zemin hazırlamıştır?', 'Gurlu komutanı Kutbeddin Aybek\'in Hindistan\'da bağımsızlaşması', ['Gurluların Moğollara bağlanması', 'Gurluların Bizans\'la ittifak yapması', 'Gurluların Anadolu\'ya göç etmesi'], 'Muizzeddin Muhammed Gori\'nin ölümünden sonra Hindistan\'daki komutanı Kutbeddin Aybek Delhi\'de bağımsız sultanlığını kurdu.'),
  ('Delhi Sultanlığı\'nın Tuğluk hanedanından Muhammed bin Tuğluk\'un başkenti Delhi\'den Devletabad\'a taşımaya çalışması nasıl sonuçlanmıştır?', 'Halk büyük sıkıntılar yaşamış ve karar geri alınmıştır', ['Devletabad kalıcı başkent olmuştur', 'Moğollar Delhi\'yi ele geçirmiştir', 'Sultanlık Bizans\'a bağlanmıştır'], 'Uzun yolculukta çok sayıda kişi öldü; plan başarısız olunca başkent yeniden Delhi\'ye taşındı.'),
  ('Ünlü seyyah İbn Battuta\'nın bir süre kadılık yaptığı Türk-İslam devleti hangisidir?', 'Delhi Sultanlığı', ['Memlük Devleti', 'Altın Orda', 'Karahanlılar'], 'İbn Battuta Muhammed bin Tuğluk döneminde Delhi\'de yıllarca kadılık yaptı; Altın Orda ve Memlük topraklarını ise yolculuk sırasında ziyaret etti.'),
  ('Memlük Devleti\'nde sultanın Kahire\'deki kalede oturması ve emirlerin kale çevresinde konaklaması, yönetimin hangi özelliğini yansıtır?', 'Askerî bir yönetici sınıfın şehri denetlemesi', ['Yönetimin köylülere bırakılması', 'Yerel Arap aşiretlerinin yönetime hâkim olması', 'Halifenin devleti yönetmesi'], 'Memlük düzeninde siyasi güç, kalede ve kışlalarda toplanan askerî zümrenin elindeydi.'),
  ('Erzurum\'da bulunan ve Saltuklu döneminden kaldığı kabul edilen, üç kümbetten oluşan yapı topluluğu hangisidir?', 'Üç Kümbetler', ['Döner Kümbet', 'Kırkkızlar Kümbeti', 'Halime Hatun Kümbeti'], 'Erzurum Üç Kümbetler\'in en büyüğünün Saltuklu Emir Saltuk\'a ait olduğu kabul edilir.'),
  ('Artukluların Mardin\'de yaptırdığı ve bugün de ayakta olan medrese hangisidir?', 'Zinciriye Medresesi', ['Karatay Medresesi', 'Çifte Minareli Medrese', 'Gök Medrese'], 'Sultan İsa Medresesi olarak da bilinen Zinciriye, 14. yüzyıl sonunda Artuklu sultanı Melik Necmeddin İsa tarafından yaptırıldı.'),
  ('Diyarbakır Ulu Camii\'nin Selçuklu döneminde Melikşah\'ın emriyle onarılması ve Artuklular döneminde yeni eklerle genişletilmesi neyi gösterir?', 'Farklı Türk devletlerinin aynı yapıya katkıda bulunduğunu', ['Caminin yalnızca Bizans döneminden kaldığını', 'Yapının yalnız Artuklularca inşa edildiğini', 'Caminin hiçbir zaman kullanılmadığını'], 'Diyarbakır Ulu Camii\'nde Selçuklu ve Artuklu dönemlerine ait onarım ve ek yazıtları bulunur.'),
  ('Artuklu hükümdarı İlgazi ve yeğeni Belek Gazi\'nin Haçlılara karşı kazandığı başarılar sırasında esir alınan önemli Haçlı yöneticisi kimdir?', 'Kudüs Kralı II. Baudouin', ['Fransa Kralı VII. Louis', 'Alman İmparatoru Barbarossa', 'Antakya Prinkepsi Bohemond'], 'Belek Gazi 1123\'te Kudüs Kralı II. Baudouin\'i esir aldı ve Harput Kalesi\'ne hapsetti.'),
  ('Gazneli Mahmut\'un sarayında \'melikü\'ş-şuara\' (şairler sultanı) unvanıyla bulunan şair kimdir?', 'Unsuri', ['Firdevsi', 'Ömer Hayyam', 'Nizami-i Gencevi'], 'Unsuri, Gazneli Mahmut\'un saray şairlerinin başıydı; kasideleriyle sultanı övdü.'),
  ('Türkiye Selçuklu tarihi için temel kaynaklardan biri olan ve 13. yüzyılda İbn Bibi tarafından yazılan eser hangi dildedir?', 'Farsça', ['Arapça', 'Türkçe', 'Latince'], 'İbn Bibi\'nin El-Evamirü\'l-Alaiyye adlı eseri Farsça yazılmış olup II. Kılıçarslan\'dan 1280\'lere kadar olan olayları anlatır.'),
  ('Anadolu Selçuklu döneminde yazılan ve Hoca Dehhani gibi şairlerin Türkçe şiirleriyle başlayan gelişme, edebiyat tarihinde hangi sürecin başlangıcı sayılır?', 'Anadolu sahasında Türkçe edebiyatın doğuşu', ['Farsçanın Anadolu\'dan büsbütün silinmesi', 'Arap alfabesinin terk edilip Latin alfabesine geçilmesi', 'Uygur yazısının Anadolu\'da resmî yazı olması'], 'Hoca Dehhani, Anadolu\'da Türkçe şiir yazan ilk divan şairlerinden kabul edilir.'),
  ('Talas Savaşı\'nın ardından Karlukların İslamiyet\'e yakınlaşması ve sonraki yüzyılda Karahanlı Devleti\'nin kuruluşunda yer alması neyi gösterir?', 'Talas\'taki yakınlaşmanın uzun vadeli siyasi sonuçlar doğurduğunu', ['Karlukların Çin\'e bağlanıp Budist kaldığını', 'Karlukların Talas\'tan sonra tamamen dağıldığını', 'Karlukların Bizans\'a göç ettiğini'], 'Talas\'ta Arapların yanında savaşan Karluklar zamanla İslam\'a yaklaştı ve Karahanlı Devleti\'nin kurucu unsurlarından oldu.'),
  ('Kutalmışoğlu Süleyman Şah\'ın Anadolu\'da İznik\'e kadar ilerlemesinde Bizans\'taki taht kavgalarının nasıl bir etkisi olmuştur?', 'Taht adaylarının Türk desteği araması Türklerin batıya ilerlemesini kolaylaştırmıştır', ['Bizans\'ın Türkleri Anadolu\'dan çıkarmasını sağlamıştır', 'Süleyman Şah\'ın Mısır\'a yönelmesine yol açmıştır', 'Taht kavgalarının Türklerle hiçbir ilgisi olmamıştır'], 'Bizans\'taki iç çatışmalarda bazı taht adayları Süleyman Şah\'tan yardım istedi; bu durum Türklerin Marmara\'ya kadar ulaşmasını kolaylaştırdı.'),
  ('Danişmentli Gümüştekin Ahmed Gazi\'nin Haçlılara ve Bizans\'a karşı kazandığı başarılar üzerine Abbasi halifesi ve Büyük Selçuklu sultanından aldığı unvan hangisidir?', 'Melik', ['Sultan', 'Atabey', 'Emirü\'l-Ümera'], 'Gümüştekin Gazi, halife ve Büyük Selçuklu sultanından \'melik\' unvanını aldı; bu, beyliğin itibarını yükseltti.'),
  ('Celaleddin Harzemşah\'ın Azerbaycan\'da devlet kurma çabası sırasında Gürcülere karşı kazandığı zaferle 1226\'da aldığı şehir hangisidir?', 'Tiflis', ['Ani', 'Ahlat', 'Erzurum'], 'Celaleddin, Gürcü ordusunu yenerek Tiflis\'i ele geçirdi; ancak Moğol baskısı nedeniyle burada kalıcı olamadı.'),
  ('Harzemşah hükümdarlarının ordularında Kıpçak Türklerine geniş yer vermesi, ordunun yapısında hangi sorunu doğurmuştur?', 'Hükümdar ile Kıpçak komutanlar arasında güven sorunu', ['Ordunun tamamen Arap askerlerinden oluşması', 'Askerlerin Türkçe bilmemesi', 'Ordunun denizcilikte uzmanlaşması'], 'Alaeddin Muhammed\'in annesi Terken Hatun\'un Kıpçak akrabaları orduda güçlüydü; bu durum hükümdarın otoritesini sınırladı.'),
  ('Bir tarihçi, Gazneli Mahmut\'un Hindistan\'dan getirdiği ganimetlerle Gazne\'de cami ve medrese yaptırmasını ele alıyor. Bu durumun Gazne\'ye etkisi en doğru şekilde nasıl değerlendirilebilir?', 'Seferler bir kültür merkezinin oluşmasını finanse etmiştir', ['Seferler Gazne\'yi yoksullaştırmıştır', 'Ganimetler yalnız Bağdat\'a gönderilmiştir', 'Seferler kültürel hayatı tamamen durdurmuştur'], 'Hint ganimetleri Gazne\'nin imarında ve bilgin ile sanatçıların himayesinde kullanıldı.'),
  ('Bir tarih öğretmeni, Babai İsyanı ile Sultan Sencer döneminde çıkan Oğuz isyanının benzer yönünü soruyor. Doğru cevap hangisidir?', 'İkisinde de Türkmenlerin yönetime ve vergilere tepkisi belirleyicidir', ['İkisi de Haçlıların kışkırtmasıyla çıkmıştır', 'İkisi de Bizans topraklarında yaşanmıştır', 'İkisi de Moğolların zaferiyle bastırılmıştır'], '1153 Oğuz isyanı vergi memurlarının tutumuna, Babai İsyanı ise Türkmenlerin ekonomik ve sosyal sıkıntılarına dayanır.'),
];
